 function sourceBlocks(){const stored=(extractedContent||contentText).trim();const digital=readDigital(stored);const raw:string=typeof digital?.source==="string"?digital.source:stored;const sentences=raw.split(/(?<=[.!?])\s+|\n+/).map(x=>x.replace(/\s+/g," ").trim()).filter(x=>x.length>2);const lines=sentences.length?sentences:[raw].filter(Boolean);const short=lines.filter(x=>x.length>=4&&x.length<90&&!/[.!?]$/.test(x));const headings=(short.length?short:lines.map(x=>x.split(/[:–—-]/)[0]).filter(x=>x.length<90)).slice(0,6);const dates=raw.match(/\b(?:19|20)\d{2}\b/g)||[];const numbers=raw.match(/\b\d+(?:[.,]\d+)?\s*(?:%|€|M|k)?\b/g)||[];const names=contentFiles.map(x=>x.replace(/\.[^.]+$/,"").replace(/[-_]/g," ")).filter(x=>!/^[0-9a-f -]{16,}$/i.test(x)&&!/^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(x));const sections=digital?.sections||Array.from({length:Math.min(6,Math.max(1,Math.ceil(lines.length/3)))},(_,i)=>{const start=i*Math.ceil(lines.length/Math.min(6,Math.max(1,Math.ceil(lines.length/3))));const part=lines.slice(start,start+Math.ceil(lines.length/Math.min(6,Math.max(1,Math.ceil(lines.length/3)))));return {title:headings[i]||("Partie "+String(i+1).padStart(2,"0")),text:part.join(" ")}}).filter(x=>x.text);return {lines,headings,sections,dates:digital?.timeline||[...new Set(dates)].slice(0,6),numbers:digital?.metrics||[...new Set(numbers)].slice(0,6),names}}
 async function extractImportedContent(){setComposing(true);setExtractStatus("Lecture du support…");try{let chunks:string[]=[];const ocr=async(source:any,label:string)=>{setExtractStatus("Lecture OCR · "+label+"…");const Tesseract=await import("tesseract.js");const result=await Tesseract.recognize(source,"fra+eng",{logger:(m:any)=>{if(m.status==="recognizing text")setExtractStatus("Lecture OCR · "+label+" · "+Math.round((m.progress||0)*100)+"%")}});return result.data.text||""};for(const file of pendingFiles){const ext=file.name.split(".").pop()?.toLowerCase();if(file.type.startsWith("image/")||["png","jpg","jpeg","webp","bmp"].includes(ext||"")){chunks.push(await ocr(file,file.name));continue}if(ext==="txt"||ext==="csv"||ext==="md"||ext==="html"){chunks.push(await file.text());continue}if(ext==="docx"){setExtractStatus("Lecture du document Word…");const mammoth=await import("mammoth");const r=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});chunks.push(r.value);continue}if(ext==="pptx"){setExtractStatus("Lecture du PowerPoint…");const JSZip=(await import("jszip")).default;const zip=await JSZip.loadAsync(await file.arrayBuffer());const slides=Object.keys(zip.files).filter(x=>/^ppt\/slides\/slide\d+\.xml$/.test(x)).sort((a,b)=>(Number(a.match(/\d+/)?.[0])||0)-(Number(b.match(/\d+/)?.[0])||0));for(const p of slides){const xml=await zip.file(p)?.async("text")||"";const doc=new DOMParser().parseFromString(xml,"application/xml");chunks.push(Array.from(doc.getElementsByTagName("a:t")).map(n=>n.textContent||"").join("\n"))}continue}if(ext==="pdf"){setExtractStatus("Lecture du PDF…");const pdfjs=await import("pdfjs-dist");pdfjs.GlobalWorkerOptions.workerSrc="https://unpkg.com/pdfjs-dist@5.4.149/build/pdf.worker.min.mjs";const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let pages:string[]=[];for(let n=1;n<=Math.min(pdf.numPages,40);n++){const page=await pdf.getPage(n);const tc=await page.getTextContent();let pageText=tc.items.map((it:any)=>"str" in it?it.str:"").join(" ").trim();if(pageText.length<80){setExtractStatus("PDF image détecté · OCR page "+n+"/"+Math.min(pdf.numPages,40));const viewport=page.getViewport({scale:1.8});const canvas=document.createElement("canvas");canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);const ctx=canvas.getContext("2d");if(ctx){await page.render({canvasContext:ctx,viewport,canvas} as any).promise;pageText=await ocr(canvas,"page "+n)}}pages.push(pageText)}chunks.push(pages.join("\n"));continue}}const clean=cleanOcr(chunks.join("\n").replace(/[ \t]+/g," ").replace(/\n{3,}/g,"\n\n"));let composed=clean?buildDigitalContent(clean):"";setExtractedContent(composed);setExtractStatus(clean?"Ressource analysée · structure pédagogique prête":"Aucun texte lisible détecté, même après lecture OCR.");setContentAnalysisReady(true);requestAnimationFrame(()=>document.getElementById("composition-results")?.scrollIntoView({behavior:"smooth",block:"start"}))}catch(e){console.error(e);setExtractStatus("Impossible de lire automatiquement ce support");setContentAnalysisReady(true)}finally{setComposing(false)}}
 function saveCurrentSequence(){const activity:ActivityDraft[] = activityName?[{title:activityName,kind:activityName==="Quiz"?"quiz":activityName==="Questionnaire"?"survey":"game",subtitle:""}]:[];const next={title:sequenceName||`Séquence ${sequences.length+1}`,objective,layout:courseLayout,content:extractedContent||contentText,color:sequenceColor,activities:activity,visuals:contentPreviews};setSequences(v=>{const idx=v.findIndex(q=>q.title===next.title);return idx>=0?v.map((q,i)=>i===idx?next:q):[...v,next]});setIsNewSequence(false);return next}
 function startNextSequence(){saveCurrentSequence();setIsNewSequence(true);setSequenceName(`Séquence ${sequences.length+2}`);setObjective("");setContentText("");setExtractedContent("");setContentFiles([]);setPendingFiles([]);setContentPreviews([]);setContentAnalysisReady(false);setExtractStatus("");setActivityName("");setSequenceColor(palette[(sequences.length+1)%palette.length]);setStep(2)}
 function importSequences(){const lines=sequenceImport.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return;const parsed=lines.map((line,i)=>{const clean=line.replace(/^\s*(?:\d+[.)-]?|[-•])\s*/,"");const parts=clean.split(/\s*[|;]\s*/);return {title:parts[0]||`Séquence ${sequences.length+i+1}`,objective:parts[1]||"",layout:"program",content:"",color:palette[(sequences.length+i)%palette.length],activities:[] as ActivityDraft[]}});setSequences(v=>[...v,...parsed]);setSequenceImport("");setSequenceName(`Séquence ${sequences.length+parsed.length+1}`)}
 async function publishCourse(){const current={title:sequenceName||`Séquence ${sequences.length+1}`,objective,layout:courseLayout,content:extractedContent||contentText,color:sequenceColor,activities:activityName?[{title:activityName,kind:activityName==="Quiz"?"quiz":activityName==="Questionnaire"?"survey":"game",subtitle:""} as ActivityDraft]:[]};const currentIndex=sequences.findIndex(q=>q.title===current.title);const seqs=currentIndex>=0?sequences.map((q,i)=>i===currentIndex?current:q):[...sequences,current];if(demoMode){const demoPub:Publication={id:`demo-${Date.now()}`,title:competence||title||"Sans titre",description:description||null,pedagogical_objective:current.objective||null,layout:current.layout,content_text:current.content||null,is_published:true,modules:seqs.map(q=>({title:q.title,activities:q.activities.map(a=>({title:a.title,activity_type:a.kind})),pedagogical_objective:q.objective,layout:q.layout,content_text:q.content} as any)),competencies:competence?[{title:competence}]:[]};saveDemoPublications([demoPub,...publications]);clearPublishedDraft();setPublished(true);setPublicationStatus("published");setSelectedPublication(demoPub);setLearnerLevel("competence");setLearnerSequenceIndex(0);setLearnerSequenceOpened(false);setView("learnerPreview");return}setSaving(true);try{const code=`F-${Date.now()}`;const cr=await api("courses",{method:"POST",body:JSON.stringify({code,title:competence||title||"Sans titre",description,pedagogical_objective:current.objective,layout:current.layout,content_text:current.content,is_published:true})},accessToken);if(!cr.ok)throw new Error(await cr.text());const [course]=await cr.json();await uploadCourseFiles(course.id);if(competence)await api("competencies",{method:"POST",body:JSON.stringify({course_id:course.id,code:"C1",title:competence})},accessToken);const allSequences=seqs;for(let i=0;i<allSequences.length;i++){const seq=allSequences[i];const mr=await api("modules",{method:"POST",body:JSON.stringify({course_id:course.id,title:seq.title,position:i+1,is_published:true,pedagogical_objective:seq.objective,layout:seq.layout,content_text:seq.content,color:seq.color})},accessToken);const [mod]=mr.ok?await mr.json():[];if(mod)for(let a=0;a<seq.activities.length;a++){const act=seq.activities[a];await api("activities",{method:"POST",body:JSON.stringify({module_id:mod.id,title:act.title,activity_type:act.kind,position:a+1,is_published:true})},accessToken)}}clearPublishedDraft();setPublished(true);setPublicationStatus("published");await loadPublications();const fresh=await api(`courses?id=eq.${course.id}&select=*,modules(title,pedagogical_objective,layout,content_text,color,position,activities(title,activity_type)),competencies(title)`,{},accessToken);if(fresh.ok){const rows=await fresh.json();if(rows?.[0])setSelectedPublication(rows[0])}setView("learnerPreview")}catch(e){alert("La publication n’a pas pu être enregistrée. Réessayez.")}finally{setSaving(false)}}
 async function togglePublication(p:Publication){if(demoMode){saveDemoPublications(publications.map(x=>x.id===p.id?{...x,is_published:!x.is_published}:x));return}await api(`courses?id=eq.${p.id}`,{method:"PATCH",body:JSON.stringify({is_published:!p.is_published})},accessToken);await loadPublications()}
 async function deletePublication(p:Publication){if(!confirm(`Supprimer définitivement « ${p.title} » ?`))return;if(demoMode){saveDemoPublications(publications.filter(x=>x.id!==p.id));if(selectedPublication?.id===p.id)setSelectedPublication(null);return}await api(`courses?id=eq.${p.id}`,{method:"DELETE"},accessToken);if(selectedPublication?.id===p.id)setSelectedPublication(null);await loadPublications()}
 if(!accessToken&&!demoMode)return <main className="studio"><header className="studio-nav"><button className="studio-brand"><span className="am-logo" aria-label="AM"><img src="/icon.svg" alt="AM"/></span><div><strong>STUDIO</strong><small>LMS FORMATEUR</small></div></button></header><section className="auth-page"><div className="auth-card showcase-auth"><span>DÉCOUVRIR LMS FORMATEUR</span><h1>{welcomeMode==="welcome"?"Bienvenue":welcomeMode==="guest"?"Découvrir la plateforme":"Accéder à mon compte"}</h1>{welcomeMode==="welcome"?<><p>Explorez l’espace formateur comme une véritable plateforme de démonstration.</p><button className="primary demo-primary" onClick={()=>{setWelcomeMode("guest");setAuthError("")}}>CONTINUER SANS COMPTE →</button><button className="auth-switch account-access" onClick={()=>{setWelcomeMode("login");setAuthMode("login");setAuthError("")}}>ACCÉDER À MON COMPTE</button><small className="showcase-note">Version vitrine · aucun engagement</small></>:welcomeMode==="guest"?<><p>Entrez simplement votre prénom et votre nom. Votre espace de démonstration sera créé sur cet appareil.</p><input autoFocus placeholder="Prénom et nom" value={demoName} onChange={e=>setDemoName(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")continueDemo()}}/>{authError&&<p className="auth-error">{authError}</p>}<button className="primary demo-primary" onClick={continueDemo}>CRÉER MON ESPACE DE DÉMONSTRATION →</button><button className="auth-switch" onClick={()=>{setWelcomeMode("welcome");setAuthError("")}}>← RETOUR</button></>:<><p>Retrouvez un espace déjà créé sur cet appareil ou connectez-vous à un compte sécurisé.</p>{savedDemoProfiles.length>0&&<div className="saved-profiles"><small>ESPACES DÉJÀ CRÉÉS</small>{savedDemoProfiles.map((p,i)=><div className="saved-profile-row" key={i}><button onClick={()=>openDemoProfile(p.name)}><span className="saved-avatar">{p.name.split(" ").filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join("")}</span><strong>{p.name}</strong><b>→</b></button><button className="delete-profile" title={`Supprimer ${p.name}`} onClick={()=>{if(!confirm(`Supprimer définitivement l’espace de démonstration « ${p.name} » et ses contenus enregistrés sur cet appareil ?`))return;localStorage.removeItem(`trainer-demo-publications:${p.name}`);localStorage.removeItem(`trainer-drafts:demo:${p.name}`);const next=savedDemoProfiles.filter(x=>x.name!==p.name);localStorage.setItem("trainer-demo-profiles",JSON.stringify(next));setSavedDemoProfiles(next)}}>SUPPRIMER</button></div>)}</div>}<div className="secure-login-label">COMPTE FORMATEUR SÉCURISÉ</div><div className="auth-tabs"><button className={authMode==="login"?"active":""} onClick={()=>{setAuthMode("login");setAuthError("")}}>SE CONNECTER</button><button className={authMode==="signup"?"active":""} onClick={()=>{setAuthMode("signup");setAuthError("")}}>CRÉER UN COMPTE</button></div>{authMode==="signup"&&<input type="text" placeholder="Prénom et nom" value={authName} onChange={e=>setAuthName(e.target.value)}/>}<input type="email" placeholder="Adresse e-mail" value={authEmail} onChange={e=>setAuthEmail(e.target.value)}/><input type="password" placeholder="Mot de passe" value={authPassword} onChange={e=>setAuthPassword(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")authenticate()}}/>{authError&&<p className="auth-error">{authError}</p>}<button className="primary" onClick={authenticate}>{authMode==="login"?"SE CONNECTER":"CRÉER MON COMPTE FORMATEUR"}</button><small className="showcase-note">Compte sécurisé · requis pour utiliser l’IA DeepSeek</small><button className="auth-switch" onClick={()=>{setWelcomeMode("welcome");setAuthError("")}}>← RETOUR À L’ACCUEIL</button></>}</div></section></main>;
